            public float Max = 1.5f;
        }

        /// <summary>An XZ point in the web's frame. Convert it.</summary>
        public struct NpcPointSpec
        {
            public float X;
            public float Z;

            /// <summary>Unconverted. Feed it to <see cref="Convert.Pos(Vector3)"/>.</summary>
            public Vector3 Raw => new Vector3(X, 0f, Z);
        }

        /// <summary>
        /// An axis-aligned XZ rectangle of pavement, right-handed.
        ///
        /// <b>Not <see cref="RectSpec"/>, and that is not an oversight.</b> The same rectangle is
        /// spelled <c>minX/maxX/minZ/maxZ</c> in <c>lotCars.bounds</c> and <c>xMin/xMax/zMin/zMax</c>
        /// here, in the original. Newtonsoft matches by name, so one class cannot read both.
        ///
        /// Negating X swaps the two X bounds: <c>xMin</c> becomes the Unity <c>xMax</c>. Convert both
        /// corners through <see cref="Convert.Pos(Vector3)"/> and re-derive min/max — never negate a
        /// field in place.
        /// </summary>
        public class NpcRectSpec
        {
            public float XMin;
            public float XMax;
            public float ZMin;
            public float ZMax;
        }

        /// <summary>A painted rectangle with a name and its own headcount. Manual mode only.</summary>
        public class NpcZoneSpec : NpcRectSpec
        {
            public string Id;

            /// <summary>Null falls back to <see cref="NpcSpec.DefaultPerZone"/>.</summary>
            public int? Count;
        }

        /// <summary>
        /// One sidewalk strip: people walk back and forth between <see cref="A"/> and <see cref="B"/>.
        ///
        /// Two points, never more — so the web's centripetal Catmull-Rom through them is a straight
        /// line, and the port resamples the segment only to bake a ground height per sample.
        /// </summary>
        public class NpcStripSpec
        {
            public string Id;
            public NpcPointSpec A;
            public NpcPointSpec B;

            /// <summary>Null falls back to <see cref="NpcSpec.PerStrip"/>. Three strips override it.</summary>
            public int? Count;
        }

        /// <summary>A mission character pinned to a route, idling at each end. U29.</summary>
        public class PlacedCharacterSpec
        {
            public PersonSpec Spec;
            public NpcPointSpec A;
            public NpcPointSpec B;
            public float IdleTime;
        }

        /// <summary>
        /// One authored street. The exporter emits two shapes for this — a bare array of points for
        /// an ordinary street, or an object with lane metadata for a divided road — which is why it
        /// needs <see cref="StreetSpecConverter"/> rather than falling out of the model.
        /// </summary>
        [JsonConverter(typeof(StreetSpecConverter))]
        public class StreetSpec
        {
            public List<Vec3> Pts = new();

            /// <summary>Lanes per direction. 1 for an ordinary street.</summary>
            public int Lanes = 1;

            /// <summary>Innermost lane's offset from the centreline; null falls back to the global one.</summary>
            public float? LaneOffset;
        }

        /// <summary>Reads a street as either <c>[{x,z}, ...]</c> or <c>{pts, lanes, laneOffset}</c>.</summary>
        public class StreetSpecConverter : JsonConverter
        {
            public override bool CanConvert(System.Type objectType) => objectType == typeof(StreetSpec);

            public override bool CanWrite => false;

            public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer) =>
                throw new System.NotSupportedException();

            public override object ReadJson(
                JsonReader reader, System.Type objectType, object existingValue, JsonSerializer serializer)
            {
                var token = Newtonsoft.Json.Linq.JToken.ReadFrom(reader);
                if (token.Type == Newtonsoft.Json.Linq.JTokenType.Array)
                    return new StreetSpec { Pts = token.ToObject<List<Vec3>>() };

                var obj = (Newtonsoft.Json.Linq.JObject)token;
                return new StreetSpec
                {
                    Pts = obj["pts"]?.ToObject<List<Vec3>>() ?? new List<Vec3>(),
                    Lanes = obj["lanes"]?.ToObject<int>() ?? 1,
                    LaneOffset = obj["laneOffset"]?.ToObject<float>(),
                };
            }
        }

        /// <summary>
        /// Traffic lights. U16 needed exactly one number from here — <see cref="SideOffset"/>, the
        /// centreline-to-kerb distance that sets how wide a crossing is. U17 uses the rest.
        ///
        /// The cycle is the Israeli one: red → red+yellow → green → yellow → red, two phase groups
        /// alternating. One half-cycle is <c>green + yellow + allRed + redYellow</c> = 13 s here, so
        /// a full cycle is 26 s and a pedestrian waits at most ~11.5 s.
        /// </summary>
        public class LightsSpec
        {
            public float GreenSec = 8f;
            public float YellowSec = 2.5f;
            public float RedYellowSec = 1.5f;
            public float AllRedSec = 1f;
            public float PoleHeight = 4.5f;

            /// <summary>Radius of the post's collider. Just the post — nothing reaches the head.</summary>
            public float PoleColliderRadius = 0.18f;

            /// <summary>Lamp size on the procedural fallback pole, metres.</summary>
            public float HeadSize = 0.35f;

            /// <summary>Metres from the centreline to the kerb — half the carriageway.</summary>
            public float SideOffset = 4.5f;

            public string ModelUrl;

            /// <summary>The GLB's own height in model units; <see cref="PoleHeight"/> / this is the scale.</summary>
            public float ModelNativeHeight = 78.64f;

            /// <summary>Extra yaw applied to the model on top of the approach heading, radians.</summary>
            public float ModelYawTune;
        }
    }
}
